function md_sales(array $rows,string $from,string $to,array $first,bool $new):array{$m=['sales'=>0.0,'profit'=>0.0,'lbs'=>0.0,'inv'=>[],'cr'=>[],'cust'=>[],'prod'=>[],'codes'=>[],'new'=>[]];foreach($rows as $r){$d=of_date($r['INV. Date']??'');if(!$d||$d<$from||$d>$to)continue;$t=strtolower(trim((string)($r['Doc Type']??'')));if(!in_array($t,['invoiced','credit'],true))continue;$n=trim((string)($r['INV#']??''));if($n!=='')$m[$t==='invoiced'?'inv':'cr'][$n]=true;$m['sales']+=of_num($r['Sales $$']??0);$m['profit']+=of_num($r['Profit $$']??0);$m['lbs']+=of_num($r['LBS']??0);$c=trim((string)($r['Cust Name']??''));if($c!==''){$k=md_id($r['Cust#']??'',$c);$m['cust'][$k]=true;if($new&&isset($first[$k])&&$first[$k]>=$from&&$first[$k]<=$to)$m['new'][$k]=true;}$p=trim((string)($r['Product Name']??''));if($p!=='')$m['prod'][md_key($p)]=true;$pc=trim((string)($r['Product Number']??''));if($pc!=='')$m['codes'][md_key($pc)]=true;}return['sales'=>$m['sales'],'profit'=>$m['profit'],'lbs'=>$m['lbs'],'invoice_count'=>count($m['inv']),'credit_count'=>count($m['cr']),'customer_count'=>count($m['cust']),'product_count'=>count($m['prod']),'product_code_count'=>count($m['codes']),'new_customer_count'=>count($m['new']),'gp_pct'=>abs($m['sales'])>0.001?$m['profit']/$m['sales']:0,'avg_invoice_sales'=>count($m['inv'])?$m['sales']/count($m['inv']):0,'profit_per_lb'=>abs($m['lbs'])>0.001?$m['profit']/$m['lbs']:0];}
function md_purchases(array $rows,string $from,string $to,array $first):array{$sp=0;$lbs=0;$pos=[];$sup=[];$prod=[];$codes=[];$new=[];foreach($rows as $r){$d=of_date($r['Receipt Date']??'');if(!$d||$d<$from||$d>$to)continue;$sp+=of_num($r['Total Item Cost']??0);$lbs+=of_num($r['LBs Received']??0);$pn=trim((string)($r['PO Number']??''));if($pn!=='')$pos[$pn]=true;$s=trim((string)($r['Supplier Name']??''));if($s!==''){$k=md_id($r['Supplier Number']??'',$s);$sup[$k]=true;if(isset($first[$k])&&$first[$k]>=$from&&$first[$k]<=$to)$new[$k]=true;}$p=trim((string)($r['Product Name']??''));if($p!=='')$prod[md_key($p)]=true;$pc=trim((string)($r['Product Number']??''));if($pc!=='')$codes[md_key($pc)]=true;}return['spend'=>$sp,'lbs'=>$lbs,'po_count'=>count($pos),'supplier_count'=>count($sup),'product_count'=>count($prod),'product_code_count'=>count($codes),'new_supplier_count'=>count($new)];}
