    if($d>=$y0&&$d<=$y1){$m=(int)substr($d,5,2);$monthly[$m]['ytd']+=$sales;if($ck!==''){$customerMove[$ck]['name']=$c;$customerMove[$ck]['ytd']=($customerMove[$ck]['ytd']??0)+$sales;}}
    elseif($d>=$p0&&$d<=$p1){$m=(int)substr($d,5,2);$monthly[$m]['pytd']+=$sales;if($ck!==''){$customerMove[$ck]['name']=$c;$customerMove[$ck]['pytd']=($customerMove[$ck]['pytd']??0)+$sales;}}
}
$moveCounts=['New'=>0,'Growing'=>0,'Stable'=>0,'Declining'=>0,'Lost / No YTD'=>0];
