$op=['pos'=>[],'sup'=>[],'prod'=>[],'codes'=>[],'lbs'=>0.0,'spend'=>0.0,'old'=>[]];foreach($po as $r){$n=trim((string)($r['PO Number']??''));if($n!=='')$op['pos'][$n]=true;$s=trim((string)($r['Supplier Name']??''));if($s!=='')$op['sup'][md_id($r['Supplier Number']??'',$s)]=true;$p=trim((string)($r['Product Name']??''));if($p!=='')$op['prod'][md_key($p)]=true;$pc=trim((string)($r['Product Number']??''));if($pc!=='')$op['codes'][md_key($pc)]=true;$op['lbs']+=of_num($r['LBS']??0);$op['spend']+=of_num($r['Total Cost']??0);$d=of_date($r['PO Date']??'');if($n!==''&&$d&&max(0,(int)(new DateTimeImmutable($d))->diff($today)->format('%a'))>30)$op['old'][$n]=true;}
// Largest negative customer/product sales variances.
