<?php
$chartColors=['#2563eb','#0ea5e9','#10b981','#f59e0b','#f97316','#dc2626'];
function md_pie_style(array $aging,string $field,array $colors):string{
    $total=0.0;foreach($aging as $a)$total+=(float)($a[$field]??0);if($total<=0)return 'background:#eef2f6';
    $parts=[];$start=0.0;$i=0;foreach($aging as $a){$v=max(0.0,(float)($a[$field]??0));$pct=$total>0?($v/$total*100):0;$end=$start+$pct;$parts[]=$colors[$i%count($colors)].' '.number_format($start,4,'.','').'% '.number_format($end,4,'.','').'%' ;$start=$end;$i++;}
    return 'background:conic-gradient('.implode(',',$parts).')';
}
$valueTotal=array_sum(array_map(fn($a)=>(float)$a['value'],$aging));
$poundTotal=array_sum(array_map(fn($a)=>(float)$a['lbs'],$aging));
?>
<div class="chart-grid">
 <section class="chart-card"><h3>Inventory Value by Age</h3><p>Current inventory value split by days in stock.</p><div class="chart-flex"><?php if($valueTotal>0):?><div class="pie" style="<?=md_h(md_pie_style($aging,'value',$chartColors))?>"></div><?php else:?><div class="chart-empty">No inventory value available</div><?php endif;?><div class="legend"><?php $i=0;foreach($aging as $k=>$a):$pct=$valueTotal>0?((float)$a['value']/$valueTotal*100):0;?><div class="legend-row"><span class="legend-swatch" style="background:<?=md_h($chartColors[$i%count($chartColors)])?>"></span><span class="legend-label"><?=md_h($k)?> days</span><span class="legend-value"><?=ld_money($a['value'])?> · <?=number_format($pct,1)?>%</span></div><?php $i++;endforeach;?></div></div></section>
 <section class="chart-card"><h3>Inventory Pounds by Age</h3><p>Current on-hand pounds split by days in stock.</p><div class="chart-flex"><?php if($poundTotal>0):?><div class="pie" style="<?=md_h(md_pie_style($aging,'lbs',$chartColors))?>"></div><?php else:?><div class="chart-empty">No inventory pounds available</div><?php endif;?><div class="legend"><?php $i=0;foreach($aging as $k=>$a):$pct=$poundTotal>0?((float)$a['lbs']/$poundTotal*100):0;?><div class="legend-row"><span class="legend-swatch" style="background:<?=md_h($chartColors[$i%count($chartColors)])?>"></span><span class="legend-label"><?=md_h($k)?> days</span><span class="legend-value"><?=ld_n($a['lbs'])?> lb · <?=number_format($pct,1)?>%</span></div><?php $i++;endforeach;?></div></div></section>
</div>
